phase2.fixedCode:
class Ticket implements AutoCloseable {
    String id;

    Ticket(String id) {
        this.id = id;
        System.out.println("Ticket " + id + " opened");
    }

    @Override
    public void close() {
        System.out.println("Ticket " + id + " closed");
    }
}

public class Test {
    public static void main(String[] args) {
        try (Ticket t = new Ticket("A1")) {
            System.out.println("Using ticket " + t.id);
        }
    }
}

